const F="Plus Jakarta Sans";
for(const s of ["Regular","Medium","SemiBold","Bold","ExtraBold"]) await figma.loadFontAsync({family:F,style:s});
const page = figma.root.children.find(p=>p.name.startsWith("03"));
await figma.setCurrentPageAsync(page);
const rgb=(r,g,b)=>({r:r/255,g:g/255,b:b/255});
const LIME=rgb(153,234,72), INK=rgb(1,2,5), WHITE=rgb(255,255,255), GRAY=rgb(92,95,102), BORDER=rgb(232,233,228), SOFT=rgb(244,245,240);
function mkText(chars,size,style,color,opts={}){
  const t=figma.createText(); t.fontName={family:F,style}; t.fontSize=size; t.characters=chars;
  t.fills=[{type:"SOLID",color}];
  if(opts.lh) t.lineHeight={value:opts.lh,unit:"PIXELS"};
  if(opts.w){ t.textAutoResize="HEIGHT"; t.resize(opts.w,t.height); }
  if(opts.name) t.name=opts.name;
  return t;
}
function mkAL(mode,spacing,pad,opts={}){
  const f=figma.createFrame(); f.layoutMode=mode; f.itemSpacing=spacing;
  f.paddingTop=pad[0];f.paddingRight=pad[1];f.paddingBottom=pad[2];f.paddingLeft=pad[3];
  f.primaryAxisSizingMode=opts.fixedW?"FIXED":"AUTO";
  f.counterAxisSizingMode=opts.fixedH?"FIXED":"AUTO";
  f.primaryAxisAlignItems=opts.justify||"MIN";
  f.counterAxisAlignItems=opts.align||"CENTER";
  f.fills=opts.fills||[];
  if(opts.radius!==undefined) f.cornerRadius=opts.radius;
  if(opts.name) f.name=opts.name;
  if(opts.strokes){f.strokes=opts.strokes;f.strokeWeight=opts.sw||1;}
  return f;
}
async function mkIcon(id,size,color){
  const c=await figma.getNodeByIdAsync(id);
  const i=c.createInstance(); i.resize(size,size);
  const paint={type:"SOLID",color};
  const walk=(n)=>{
    try{
      if("fills" in n && n.type!=="FRAME" && n.type!=="INSTANCE" && n.type!=="GROUP"){
        const f=n.fills; if(Array.isArray(f)&&f.length) n.fills=[paint];
        const s=n.strokes; if(Array.isArray(s)&&s.length) n.strokes=[paint];
      }
    }catch(e){}
    if("children" in n) n.children.forEach(walk);
  };
  walk(i);
  return i;
}
async function inst(id,name){
  const c=await figma.getNodeByIdAsync(id);
  const src = c.type==="COMPONENT_SET" ? c.defaultVariant : c;
  const i=src.createInstance();
  if(name)i.name=name;
  return i;
}
function findByName(root,name){return root.findOne(n=>n.name===name);}

