const fixed=[];
function fixFrame(f){
  if(f.type==="FRAME"||f.type==="COMPONENT"){
    if(f.layoutMode==="VERTICAL" && f.primaryAxisSizingMode==="FIXED" && f.counterAxisSizingMode==="AUTO"){
      const w=f.width;
      f.primaryAxisSizingMode="AUTO";
      f.counterAxisSizingMode="FIXED";
      f.resize(w,f.height);
      fixed.push(f.name+"("+f.id+") w="+Math.round(w)+" h="+Math.round(f.height));
    }
  }
  if("children" in f) f.children.forEach(fixFrame);
}
// fix components first
